<div class="d-flex justify-content-between align-items-center mb-3"><div><h1><?=$id?'View / Edit Planting':'Add Planting'?></h1><p class="text-muted">This planting remains separate from the master seed research record.</p></div><a class="btn btn-outline-secondary" href="<?=e(url('garden'))?>">Back to My Garden</a></div>
