<div class="col-md-5"><label class="form-label" for="garden-status">Status</label><select id="garden-status" class="form-select" name="status" required><?php foreach(garden_statuses() as $choice):?><option <?=($planting['status']??'')===$choice?'selected':''?>><?=e($choice)?></option><?php endforeach?></select></div>
<div class="col-md-6"><label class="form-label" for="garden-transplant">Actual transplant date</label><input id="garden-transplant" class="form-control" type="date" name="actual_transplant_date" value="<?=e($planting['actual_transplant_date']??'')?>"><div class="form-text">Authoritative; suppresses the expected transplant date.</div></div>
